from pathlib import Path
R=Path(__file__).resolve().parents[1]

def patch(rel, old, new, count=1):
    p=R/rel; t=p.read_text()
    if old not in t:
        print('MISS', rel, old[:80].replace('\n',' ')); return False
    p.write_text(t.replace(old,new,count)); print('PATCH',rel); return True

