# Same-page split is a second view of the current tab, not a second browser tab.
patch('app/src/main/java/com/uong/phormi/MainActivity.kt', '''    private var splitChromeLocked = false\n    private var splitRatio = 0.5f''', '''    private var splitChromeLocked = false\n    private var splitRatio = 0.5f\n    private var samePageSplitMode = false\n    private var samePageSplitWebView: WebView? = null''')
old='''    private fun openSamePageSplit() {\n        if (splitMode) {\n            Toast.makeText(this, "Already in split view", Toast.LENGTH_SHORT).show()\n            return\n        }\n        val source = tabs.find { it.id == activeTabId } ?: return\n        val currentUrl = source.webView.url?.takeIf { it.startsWith("http") } ?: return\n        val originalId = source.id\n        createNewTab(currentUrl, source.profileName, forceGhost = false)\n        val duplicateId = activeTabId\n        if (duplicateId == originalId || tabs.none { it.id == duplicateId }) return\n        splitTopTabId = originalId\n        splitBottomTabId = duplicateId\n        setSplitMode(true)\n    }'''
new='''    private fun openSamePageSplit() {\n        if (samePageSplitMode) {\n            Toast.makeText(this, "This page is already split", Toast.LENGTH_SHORT).show()\n            return\n        }\n        val source = activeWebView() ?: return\n        val currentUrl = source.url?.takeIf { it.startsWith("http") }\n            ?: run { Toast.makeText(this, "Open a webpage first", Toast.LENGTH_SHORT).show(); return }\n        samePageSplitMode = true\n        splitMode = true\n        samePageSplitWebView = WebView(this).also { secondary ->\n            CookieManager.getInstance().setAcceptThirdPartyCookies(secondary, true)\n            configureWebView(secondary)\n            secondary.isClickable = true\n            secondary.isFocusable = true\n            secondary.isFocusableInTouchMode = true\n            secondary.setBackgroundColor(Color.TRANSPARENT)\n            secondary.loadUrl(currentUrl)\n        }\n        (source.parent as? ViewGroup)?.removeView(source)\n        splitTopHost.removeAllViews()\n        splitBottomHost.removeAllViews()\n        splitTopHost.addView(source, FrameLayout.LayoutParams(-1, -1))\n        splitBottomHost.addView(samePageSplitWebView, FrameLayout.LayoutParams(-1, -1))\n        source.visibility = View.VISIBLE\n        samePageSplitWebView?.visibility = View.VISIBLE\n        splitContainer.visibility = View.VISIBLE\n        startPageContainer.visibility = View.GONE\n        setSplitChromeLocked(false)\n        splitRatio = 0.5f\n        splitContainer.post { applySplitRatio() }\n    }\n\n    private fun closeSamePageSplit() {\n        if (!samePageSplitMode) return\n        val source = activeWebView()\n        samePageSplitWebView?.stopLoading()\n        samePageSplitWebView?.destroy()\n        samePageSplitWebView = null\n        splitBottomHost.removeAllViews()\n        splitTopHost.removeAllViews()\n        source?.let { webViewContainer.addView(it, FrameLayout.LayoutParams(-1, -1)); it.visibility = View.VISIBLE }\n        samePageSplitMode = false\n        splitMode = false\n        splitContainer.visibility = View.GONE\n        setSplitChromeLocked(false)\n        updateStartPageVisibility()\n    }'''
patch('app/src/main/java/com/uong/phormi/MainActivity.kt', old, new)
patch('app/src/main/java/com/uong/phormi/MainActivity.kt', '        if (splitMode) setSplitMode(false)\n        startPageContainer.visibility = View.VISIBLE', '        if (samePageSplitMode) closeSamePageSplit() else if (splitMode) setSplitMode(false)\n        startPageContainer.visibility = View.VISIBLE')
patch('app/src/main/java/com/uong/phormi/MainActivity.kt', '    private fun setSplitMode(enabled: Boolean) {\n        if (enabled == splitMode) return', '    private fun setSplitMode(enabled: Boolean) {\n        if (samePageSplitMode) { if (!enabled) closeSamePageSplit(); return }\n        if (enabled == splitMode) return')

