# Keyboard: normal IME foundation, stable sizing, and editor operations in the clipboard surface.
p='app/src/main/java/com/uong/phormi/PhormiKeyboardService.kt'
text=(R/p).read_text()
start=text.index('    private fun buildKeyboard(): View {')
end=text.index('    private fun charRow(chars: String): View {')
new='''    private fun buildKeyboard(): View {\n        val root = baseRoot()\n        val type = editorInfo?.inputType ?: InputType.TYPE_CLASS_TEXT\n        val clazz = type and InputType.TYPE_MASK_CLASS\n        val variation = type and InputType.TYPE_MASK_VARIATION\n        val numeric = clazz == InputType.TYPE_CLASS_NUMBER || clazz == InputType.TYPE_CLASS_PHONE\n        val datetime = clazz == InputType.TYPE_CLASS_DATETIME\n        val email = variation == InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS || variation == InputType.TYPE_TEXT_VARIATION_WEB_EMAIL_ADDRESS\n        val uri = variation == InputType.TYPE_TEXT_VARIATION_URI || variation == InputType.TYPE_TEXT_VARIATION_WEB_EDIT_TEXT\n        val password = variation == InputType.TYPE_TEXT_VARIATION_PASSWORD || variation == InputType.TYPE_TEXT_VARIATION_VISIBLE_PASSWORD || variation == InputType.TYPE_TEXT_VARIATION_WEB_PASSWORD\n        if (password) completions = emptyList()\n        toolbar(root)\n        if (numeric) {\n            listOf("1234567890", "-/:;()\\$@", ".,#+*=").forEach { root.addView(charRow(it)) }\n        } else if (datetime) {\n            listOf("1234567890", ":-/", "AMPM").forEach { root.addView(charRow(it)) }\n        } else if (symbols) {\n            listOf("1234567890", "@#\\$%&*()", "-_=+[]{}", "\\\\|;:'\\\",./<>?!").forEach { root.addView(charRow(it)) }\n        } else {\n            val layout = when (PhormiKeyboardPreferences.layout(this)) {\n                "AZERTY" -> listOf("azertyuiop", "qsdfghjklm", "wxcvbn")\n                "QWERTZ" -> listOf("qwertzuiop", "asdfghjkl", "yxcvbnm")\n                "DVORAK" -> listOf("',.pyfgcrl", "aoeuidhtns", ";qjkxbmwvz")\n                else -> listOf("qwertyuiop", "asdfghjkl", "zxcvbnm")\n            }\n            layout.forEach { root.addView(charRow(it)) }\n        }\n        if (email || uri || numeric || datetime) {\n            val row = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL; gravity = Gravity.CENTER }\n            val tokens = when { email -> listOf("@", ".com", ".net", ".org"); uri -> listOf("/", ".com", "https://", ".org"); else -> listOf(".", ",", "-", "+") }\n            tokens.forEach { token -> key(row, token) { commitText(token) } }\n            root.addView(row, LinearLayout.LayoutParams(-1, rowHeight()))\n        }\n        val bottom = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL; gravity = Gravity.CENTER }\n        if (!numeric) {\n            key(bottom, if (symbols) "ABC" else "123", 0.85f) { symbols = !symbols; setInputView(render()) }\n            key(bottom, if (capsLock) "⇧" else if (shift) "⇧·" else "⇧", 0.85f) {\n                when { capsLock -> { capsLock = false; shift = false }; shift -> { capsLock = true; shift = false }; else -> shift = true }\n                setInputView(render())\n            }\n            key(bottom, ",", 0.7f) { commitText(",") }\n        }\n        val space = key(bottom, "space", if (numeric) 3f else 3.8f) { commitSpace() }\n        space.setOnTouchListener { _, event ->\n            when (event.actionMasked) {\n                MotionEvent.ACTION_DOWN -> { lastSpaceDownX = event.x; lastSpaceDownAt = System.currentTimeMillis(); suppressSpaceCommit = false; spaceSwipeMoved = false }\n                MotionEvent.ACTION_MOVE -> { val dx = event.x - lastSpaceDownX; if (!spaceSwipeMoved && kotlin.math.abs(dx) > 45f) { suppressSpaceCommit = true; spaceSwipeMoved = true; moveCursor(if (dx > 0) 1 else -1) } }\n                MotionEvent.ACTION_UP -> { if (!suppressSpaceCommit && System.currentTimeMillis() - lastSpaceDownAt < 650L) commitSpace(); suppressSpaceCommit = false; spaceSwipeMoved = false }\n                MotionEvent.ACTION_CANCEL -> { suppressSpaceCommit = false; spaceSwipeMoved = false }\n            }; true\n        }\n        key(bottom, ".", 0.7f) { commitText(".") }\n        key(bottom, "⌫", 0.9f) { deleteBackward() }.also { installRepeat(it) { deleteBackward() } }\n        key(bottom, "↵", 0.9f) { sendEditorAction() }\n        root.addView(bottom, LinearLayout.LayoutParams(-1, rowHeight()))\n        val utility = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL; gravity = Gravity.CENTER }\n        key(utility, "📋", 0.9f) { panel = Panel.CLIPBOARD; setInputView(render()) }\n        key(utility, "↕", 0.9f) { cycleKeyboardSize() }\n        key(utility, "←", 0.8f) { moveCursor(-1) }\n        key(utility, "→", 0.8f) { moveCursor(1) }\n        key(utility, "🎙", 0.9f) { startActivity(Intent(this, PhormiKeyboardVoiceActivity::class.java).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)) }\n        key(utility, "⌨", 0.9f) { runCatching { switchToNextInputMethod(false) } }\n        key(utility, "⚙", 0.9f) { startActivity(Intent(this, PhormiKeyboardSettingsActivity::class.java).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)) }\n        root.addView(utility, LinearLayout.LayoutParams(-1, rowHeight()))\n        return root\n    }\n\n    private fun rowHeight(): Int = (48 * PhormiKeyboardPreferences.scale(this).coerceIn(80, 120) / 100f).toInt().coerceIn(42, 62)\n\n    private fun cycleKeyboardSize() {\n        val current = PhormiKeyboardPreferences.scale(this)\n        val next = when (current) { 80 -> 90; 90 -> 100; 100 -> 110; 110 -> 120; else -> 80 }\n        PhormiKeyboardPreferences.set(this, PhormiKeyboardPreferences.KEY_SCALE, next.toString())\n        Toast.makeText(this, "Keyboard size: $next%", Toast.LENGTH_SHORT).show()\n        setInputView(render())\n    }\n\n'''
text=text[:start]+new+text[end:]
start=text.index('    private fun key(\n')
end=text.index('    private fun installRepeat(button: View, action: () -> Unit) {')
keyfun='''    private fun key(\n        row: LinearLayout,\n        label: String,\n        weight: Float = 1f,\n        action: () -> Unit\n    ): Button = Button(this).apply {\n        text = label\n        textSize = (14f * PhormiKeyboardPreferences.scale(this@PhormiKeyboardService) / 100f).coerceIn(11f, 17f)\n        setTextColor(if (PhormiKeyboardPreferences.theme(this@PhormiKeyboardService) == "Light") Color.rgb(15,23,42) else Color.WHITE)\n        minWidth = 0; minHeight = 0; includeFontPadding = false; setPadding(0,0,0,0); isAllCaps = false\n        contentDescription = label\n        background = android.graphics.drawable.GradientDrawable().apply {\n            shape = android.graphics.drawable.GradientDrawable.RECTANGLE\n            cornerRadius = 9f * resources.displayMetrics.density\n            setColor(if (PhormiKeyboardPreferences.theme(this@PhormiKeyboardService) == "Light") Color.rgb(255,255,255) else Color.rgb(31,41,55))\n            setStroke((resources.displayMetrics.density).toInt().coerceAtLeast(1), if (PhormiKeyboardPreferences.theme(this@PhormiKeyboardService) == "Light") Color.rgb(203,213,225) else Color.rgb(55,65,81))\n        }\n        setOnClickListener {\n            if (PhormiKeyboardPreferences.haptic(this@PhormiKeyboardService)) performHapticFeedback(android.view.HapticFeedbackConstants.KEYBOARD_TAP)\n            if (PhormiKeyboardPreferences.sound(this@PhormiKeyboardService)) playSoundEffect(android.view.SoundEffectConstants.CLICK)\n            action()\n        }\n        if (PhormiKeyboardPreferences.keyPopup(this@PhormiKeyboardService) && label.length == 1 && label[0].isLetter()) {\n            setOnLongClickListener {\n                val alternatives = when (label.lowercase()) {\n                    "a" -> "áàâäãå"; "e" -> "éèêëē"; "i" -> "íìîïī"; "o" -> "óòôöõ"; "u" -> "úùûüū"; "n" -> "ñńň"; "c" -> "çćč"; "s" -> "śšß"; "z" -> "źžż"; else -> ""\n                }\n                if (alternatives.isBlank()) return@setOnLongClickListener false\n                androidx.appcompat.app.AlertDialog.Builder(this@PhormiKeyboardService).setTitle(label).setItems(alternatives.map { it.toString() }.toTypedArray()) { _, which -> currentInputConnection?.commitText(alternatives[which].toString(), 1) }.show()\n                true\n            }\n        }\n        row.addView(this, LinearLayout.LayoutParams(0, rowHeight(), weight).apply { setMargins(2,2,2,2) })\n    }\n\n'''
text=text[:start]+keyfun+text[end:]
text=text.replace('''    private fun copySelection() {\n        val ic = currentInputConnection ?: return\n        runCatching { ic.performContextMenuAction(android.R.id.copy) }\n    }''','''    private fun copySelection() {\n        val ic = currentInputConnection ?: return\n        val selected = runCatching { ic.getSelectedText(0)?.toString() }.getOrNull().orEmpty()\n        runCatching { ic.performContextMenuAction(android.R.id.copy) }\n        if (selected.isNotBlank() && !PhormiKeyboardPreferences.incognito(this)) {\n            runCatching {\n                val cm = getSystemService(Context.CLIPBOARD_SERVICE) as ClipboardManager\n                cm.setPrimaryClip(android.content.ClipData.newPlainText("Phormi", selected))\n                PhormiKeyboardClipboardStore.capturePrimaryClipboard(this)\n            }\n        }\n    }''',1)
start=text.index('    private fun moveCursor(delta: Int) {')
end=text.index('    private fun sendEditorAction()', start)
text=text[:start]+'''    private fun moveCursor(delta: Int) {\n        val ic = currentInputConnection ?: return\n        runCatching {\n            val code = if (delta < 0) KeyEvent.KEYCODE_DPAD_LEFT else KeyEvent.KEYCODE_DPAD_RIGHT\n            ic.sendKeyEvent(KeyEvent(KeyEvent.ACTION_DOWN, code))\n            ic.sendKeyEvent(KeyEvent(KeyEvent.ACTION_UP, code))\n        }\n    }\n\n'''+text[end:]
(R/p).joinpath('app/src/main/java/com/uong/phormi/PhormiKeyboardService.kt').write_text(text)

