# Smart context emoji suggestions live inside the emoji surface; generated stickers remain in the sticker surface.
patch('app/src/main/java/com/uong/phormi/PhormiKeyboardService.kt', '''        key(cats, "ABC") { panel = Panel.KEYBOARD; setInputView(render()) }\n        nav.addView(cats)\n        root.addView(nav, LinearLayout.LayoutParams(-1, 48))''', '''        key(cats, "✨ AI") { insertContextEmojiSuggestions() }\n        key(cats, "ABC") { panel = Panel.KEYBOARD; setInputView(render()) }\n        nav.addView(cats)\n        root.addView(nav, LinearLayout.LayoutParams(-1, 48))''')
patch('app/src/main/java/com/uong/phormi/PhormiKeyboardService.kt', '''    override fun onConfigureWindow(win: Window, isFullscreen: Boolean, isCandidatesOnly: Boolean) {''', '''    private fun insertContextEmojiSuggestions() {\n        val context = currentInputConnection?.getTextBeforeCursor(120, 0)?.toString()?.lowercase().orEmpty()\n        val emojis = when {\n            listOf("happy", "great", "love", "congrats", "congratulations", "good", "yay", "win").any { context.contains(it) } -> listOf("😊", "🥳", "🎉", "❤️", "👏")\n            listOf("sad", "sorry", "miss", "cry", "bad", "hurt").any { context.contains(it) } -> listOf("😔", "🥺", "😭", "💔", "🫂")\n            listOf("laugh", "funny", "lol", "haha", "joke").any { context.contains(it) } -> listOf("😂", "🤣", "😆", "😭", "💀")\n            listOf("angry", "mad", "annoyed").any { context.contains(it) } -> listOf("😤", "😠", "😡", "🤬", "💢")\n            else -> listOf("😊", "👍", "❤️", "😂", "🔥")\n        }\n        val root = baseRoot()\n        root.addView(TextView(this).apply { text = "✨ AI emoji suggestions"; setTextColor(Color.WHITE); setPadding(10, 6, 10, 6) }, LinearLayout.LayoutParams(-1, rowHeight()))\n        val row = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL; gravity = Gravity.CENTER }\n        emojis.forEach { emoji -> key(row, emoji) { commitText(emoji) } }\n        root.addView(row, LinearLayout.LayoutParams(-1, rowHeight()))\n        key(root, "← Emoji") { setInputView(buildEmoji()) }\n        setInputView(root)\n    }\n\n    override fun onConfigureWindow(win: Window, isFullscreen: Boolean, isCandidatesOnly: Boolean) {''')
